"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["42944"],{12862(e){e.exports=JSON.parse('{"id":"F486","slug":"basel-capital-buffers","name":"Basel III Capital Requirement Stack and Buffers","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Basel I, II, III and the Basel III endgame","level":"Intermediate","aliases":["Basel I, II, III","capital conservation buffer","countercyclical buffer","G-SIB surcharge","maximum distributable amount","CET1 requirement"],"formula":{"latex":"\\\\text{Req}=4.5\\\\%+CCB+CCyB+G\\\\text{-}SIB,\\\\quad \\\\text{Buffer}=\\\\frac{CET1}{RWA}-\\\\text{Req}","also":[],"text":"Required CET1 ratio = 4.5% minimum + capital conservation buffer (2.5%) + countercyclical buffer (set by the country, 0% to 2.5%) + surcharge for global systemically important banks (1% to 3.5%); Headroom = actual CET1 ratio - requirement (this is the loss the bank can absorb before restrictions); Capital needed = shortfall x risk-weighted assets; Banks inside the buffers face limits on dividends and bonuses"},"symbols":[{"symbol":"CET1","meaning":"Common equity tier 1 capital (shares and retained earnings after deductions)","unit":"money"},{"symbol":"RWA","meaning":"Risk-weighted assets: assets scaled by their riskiness","unit":"money"},{"symbol":"CCB, CCyB","meaning":"Conservation buffer and countercyclical buffer","unit":"percent"},{"symbol":"G-SIB","meaning":"Extra requirement for the largest global banks","unit":"percent"}],"when_to_use":"Use it to see how much loss a bank can bear before it faces limits on payouts. The minimum is not the real constraint; the buffers on top are. Supervisors raise the countercyclical buffer in booms, so the requirement can change. It ignores other requirements such as leverage ratio, liquidity and bank-specific add-ons.","worked_example":{"problem":"A bank has CET1 capital of 12 against risk-weighted assets of 100. The countercyclical buffer is 1% and the bank is in a 1.5% systemic-bank bracket.","inputs":{"c":12,"r":100,"ccyb":1,"gs":1.5},"steps":[{"label":"CET1 ratio","working":"12 / 100","value":"12.00%"},{"label":"Requirement = 4.5% + 2.5% + CCyB + G-SIB","working":"0.045+0.025+0.01+0.015","value":"9.50%"},{"label":"Headroom","working":"0.12-0.095","value":"2.50%"},{"label":"Loss absorbable before breaching (as % of RWA)","working":"0.025 x 100","value":"2.50"},{"label":"Headroom if RWA rise 10%","working":"12 / (100 x 1.1)-0.095","value":"1.41%"}],"answer":"The bank\'s CET1 ratio is 12.00%. The requirement including buffers is 9.50%, so headroom is 2.50%. Losses of 2.50 of risk-weighted assets would use up the headroom. If RWA rise 10% the headroom becomes 1.41%."},"calculator":{"available":true,"inputs":[{"id":"c","label":"CET1 capital","unit":"money","type":"number","default":12,"hint":""},{"id":"r","label":"Risk-weighted assets","unit":"money","type":"number","default":100,"hint":""},{"id":"ccyb","label":"Countercyclical buffer","unit":"%","type":"number","default":1,"hint":""},{"id":"gs","label":"G-SIB surcharge","unit":"%","type":"number","default":1.5,"hint":""}],"checks":[{"expr":"r>0","message":"Risk-weighted assets must be above zero."}],"steps":[{"id":"ratio","label":"CET1 ratio","expr":"c/r","format":"pct2"},{"id":"req","label":"Requirement = 4.5% + 2.5% + CCyB + G-SIB","expr":"0.045+0.025+ccyb+gs","format":"pct2"},{"id":"head","label":"Headroom","expr":"ratio-req","format":"pct2"},{"id":"loss","label":"Loss absorbable before breaching (as % of RWA)","expr":"head*r","format":"money"},{"id":"head2","label":"Headroom if RWA rise 10%","expr":"c/(r*1.1)-req","format":"pct2"}],"results":["ratio","req","head","loss","head2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ratio":0.12,"req":0.095,"head":2.4999999999999994e-2,"loss":2.4999999999999996,"head2":0.01409090909090907}},"finder":{"finds":"How far a bank is above its capital requirement","needs":"CET1 capital, risk-weighted assets, buffer settings"},"related":[{"slug":"cet1-ratio","name":"CET1, Tier 1 and Leverage Ratios"},{"slug":"basel-output-floor","name":"Basel III Endgame: Output Floor on Risk-Weighted Assets"},{"slug":"stress-test-loss","name":"Stress Test Loss and Capital Buffer"}],"related_ids":["F353","F487","F380"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Req</mtext><mo>=</mo><mn>4.5</mn><mi mathvariant=\\"normal\\">%</mi><mo>+</mo><mi>C</mi><mi>C</mi><mi>B</mi><mo>+</mo><mi>C</mi><mi>C</mi><mi>y</mi><mi>B</mi><mo>+</mo><mi>G</mi><mtext>-</mtext><mi>S</mi><mi>I</mi><mi>B</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Buffer</mtext><mo>=</mo><mfrac><mrow><mi>C</mi><mi>E</mi><mi>T</mi><mn>1</mn></mrow><mrow><mi>R</mi><mi>W</mi><mi>A</mi></mrow></mfrac><mo>\u2212</mo><mtext>Req</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Req}=4.5\\\\%+CCB+CCyB+G\\\\text{-}SIB,\\\\quad \\\\text{Buffer}=\\\\frac{CET1}{RWA}-\\\\text{Req}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"barrier-option-payoff","name":"Barrier Option Payoff"},"next":{"slug":"basel-output-floor","name":"Basel III Endgame: Output Floor on Risk-Weighted Assets"},"lesson":null,"total":522}')}}]);